package com.example.notificationservice.dto.request;
import jakarta.validation.constraints.*;
public class NotificationRequest { @NotNull private Long userId; @NotBlank private String type; @NotBlank private String title; private String message; public Long getUserId(){return userId;} public void setUserId(Long v){this.userId=v;} public String getType(){return type;} public void setType(String v){this.type=v;} public String getTitle(){return title;} public void setTitle(String v){this.title=v;} public String getMessage(){return message;} public void setMessage(String v){this.message=v;} }